  3	public final class BellmanFord {
  4	    private static final int EDGE_WIDTH = 3;
  5	    private static final int INF = 100_000_000;
  6	    private static final int[] NEGATIVE_CYCLE_RESULT = {-1};
  7	
  8	    private BellmanFord() {
  9	    }
 10	
 11	    static int[] bellmanFord(int vertices, int[][] edgeData, int source) {
 12	        return shortestPaths(vertices, edgeData, source);
 13	    }
 14	
 15	    static int[] shortestPaths(int vertices, int[][] edgeData, int source) {
 16	        validateInput(vertices, edgeData, source);
 17	        return shortestPaths(vertices, toEdges(vertices, edgeData), source);
 18	    }
 19	
 20	    private static int[] shortestPaths(int vertices, Edge[] edges, int source) {
 21	        int[] distances = initializeDistances(vertices, source);
 22	
 23	        for (int pass = 0; pass < vertices - 1; pass++) {
 24	            boolean updated = false;
 25	
 26	            for (Edge edge : edges) {
 27	                updated |= relax(edge, distances);
 28	            }
 29	
 30	            if (!updated) {
 31	                return distances;
 32	            }
 33	        }
 34	
 35	        if (hasNegativeCycle(edges, distances)) {
 36	            return NEGATIVE_CYCLE_RESULT;
 37	        }
 38	
 39	        return distances;
 40	    }
 41	
 42	    private static void validateInput(int vertices, int[][] edgeData, int source) {
 43	        if (vertices <= 0) {
 44	            throw new IllegalArgumentException("vertices must be positive");
 45	        }
 46	        if (source < 0 || source >= vertices) {
 47	            throw new IllegalArgumentException("source must be within the vertex range");
 48	        }
 49	        if (edgeData == null) {
 50	            throw new IllegalArgumentException("edges must not be null");
 51	        }
 52	    }
 53	
 54	    private static int[] initializeDistances(int vertices, int source) {
 55	        int[] distances = new int[vertices];
 56	        Arrays.fill(distances, INF);
 57	        distances[source] = 0;
 58	        return distances;
 59	    }
 60	
 61	    private static boolean relax(Edge edge, int[] distances) {
 62	        if (distances[edge.from] == INF) {
 63	            return false;
 64	        }
 65	
 66	        int candidateDistance = distances[edge.from] + edge.weight;
 67	        if (candidateDistance >= distances[edge.to]) {
 68	            return false;
 69	        }
 70	
 71	        distances[edge.to] = candidateDistance;
 72	        return true;
 73	    }
 74	
 75	    private static boolean hasNegativeCycle(Edge[] edges, int[] distances) {
 76	        for (Edge edge : edges) {
 77	            if (distances[edge.from] != INF
 78	                    && distances[edge.from] + edge.weight < distances[edge.to]) {
 79	                return true;
 80	            }
 81	        }
 82	        return false;
 83	    }
 84	
 85	    private static Edge[] toEdges(int vertices, int[][] edgeData) {
 86	        Edge[] edges = new Edge[edgeData.length];
 87	        for (int i = 0; i < edgeData.length; i++) {
 88	            int[] edge = edgeData[i];
 89	            if (edge == null || edge.length != EDGE_WIDTH) {
 90	                throw new IllegalArgumentException("each edge must contain exactly 3 integers");
 91	            }
 92	
 93	            int from = edge[0];
 94	            int to = edge[1];
 95	            validateVertex(from, vertices, "edge start");
 96	            validateVertex(to, vertices, "edge end");
 97	
 98	            edges[i] = new Edge(from, to, edge[2]);
 99	        }
100	        return edges;
101	    }
102	
103	    private static void validateVertex(int vertex, int vertices, String label) {
104	        if (vertex < 0 || vertex >= vertices) {
105	            throw new IllegalArgumentException(label + " must be within the vertex range");
106	        }
107	    }
108	
109	    private static final class Edge {
110	        private final int from;
111	        private final int to;
112	        private final int weight;
113	
114	        private Edge(int from, int to, int weight) {
115	            this.from = from;
116	            this.to = to;
117	            this.weight = weight;
118	        }
119	    }
120	}

