 23	    public static Result computeShortestPaths(Graph graph, int source) {
 24	        validateSource(source, graph.vertices());
 25	        int[] distances = initializeDistances(graph.vertices(), source);
 26	
 27	        for (int pass = 0; pass < graph.vertices() - 1; pass++) {
 28	            boolean updated = false;
 29	
 30	            for (Edge edge : graph.edges()) {
 31	                updated |= relax(edge, distances);
 32	            }
 33	
 34	            if (!updated) {
 35	                return Result.success(distances);
 36	            }
 37	        }
 38	
 39	        if (hasNegativeCycle(graph.edges(), distances)) {
 40	            return Result.negativeCycle();
 41	        }
 42	
 43	        return Result.success(distances);
 44	    }
